CREATE TABLE IF NOT EXISTS TB_EEP_TRADE_M ( TRADE_SQ int NOT NULL AUTO_INCREMENT , KIND_CD varchar(4) NOT NULL COMMENT 'SALE 매출, BUY 매입' , YM char(7) NOT NULL , PARTNER_SQ int NOT NULL , TYPE_NM varchar(50) NOT NULL COMMENT '구분(임대료·장비·용역 등 자유 입력)' , ITEM_NM varchar(300) NOT NULL COMMENT '품목' , START_DT char(10) NULL , END_DT char(10) NULL , AMT bigint NOT NULL COMMENT '공급가액' , MEMO varchar(500) NULL , UPDT_EMPLY_ID varchar(50) NULL , UPDT_DT datetime NULL , PRIMARY KEY (TRADE_SQ) , KEY IX_TRADE_MONTH (KIND_CD, YM) ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='투입 외 매출·매입 건';
CREATE TABLE IF NOT EXISTS TB_EEP_TRADE_LINE_R ( KIND_CD varchar(4) NOT NULL , YM char(7) NOT NULL , SRC_CD char(1) NOT NULL COMMENT 'D 투입 건(DEPLOY_SQ), M 일반 건(TRADE_SQ)' , SRC_SQ int NOT NULL , INV_NO int NULL COMMENT '거래처 안에서 몇 번째 세금계산서' , SORT_NO int NULL COMMENT '계산서 안 순서' , AMT bigint NULL COMMENT '투입 건 금액을 손으로 고친 값' , ISSUE_DT char(10) NULL COMMENT '발급 완료로 표시한 날' , PRIMARY KEY (KIND_CD, YM, SRC_CD, SRC_SQ) ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='월별 건의 세금계산서 묶음·순서·발급 표시';
ALTER TABLE TB_EEP_TRADE_M ADD COLUMN IF NOT EXISTS PARTNER_NM varchar(200) NULL COMMENT '거래처 직접 입력' AFTER PARTNER_SQ; ALTER TABLE TB_EEP_TRADE_M MODIFY PARTNER_SQ int NULL;
INSERT INTO TB_EEP_MENU (MENU_CODE, MENU_NM, REL_CODE, MENU_DEPTH, MENU_URL, FRST_REG_DT, LAST_UPDT_DT, FRST_REGISTER, SORT_NO, USE_YN, AUTH_PATTERN, NEW_WIN_YN) SELECT 'H00009', '매출관리', REL_CODE, MENU_DEPTH, '/admin/trade/openSaleList.do', NOW(), NOW(), 'system', SORT_NO + 1, 'Y', '/admin/trade/openSaleList.do,/admin/trade/sale/**', 'N' FROM TB_EEP_MENU WHERE MENU_CODE = 'H00006' AND NOT EXISTS (SELECT 1 FROM (SELECT MENU_CODE FROM TB_EEP_MENU) M WHERE M.MENU_CODE = 'H00009'); INSERT INTO TB_EEP_MENU (MENU_CODE, MENU_NM, REL_CODE, MENU_DEPTH, MENU_URL, FRST_REG_DT, LAST_UPDT_DT, FRST_REGISTER, SORT_NO, USE_YN, AUTH_PATTERN, NEW_WIN_YN) SELECT 'H00010', '매입관리', REL_CODE, MENU_DEPTH, '/admin/trade/openBuyList.do', NOW(), NOW(), 'system', SORT_NO + 2, 'Y', '/admin/trade/openBuyList.do,/admin/trade/buy/**', 'N' FROM TB_EEP_MENU WHERE MENU_CODE = 'H00006' AND NOT EXISTS (SELECT 1 FROM (SELECT MENU_CODE FROM TB_EEP_MENU) M WHERE M.MENU_CODE = 'H00010'); INSERT IGNORE INTO TB_EEP_ROLE_MENU_R (ROLE_SQ, MENU_CODE) SELECT ROLE_SQ, 'H00009' FROM TB_EEP_ROLE_MENU_R WHERE MENU_CODE = 'H00006' AND NOT EXISTS (SELECT 1 FROM (SELECT MENU_CODE FROM TB_EEP_ROLE_MENU_R) R WHERE R.MENU_CODE = 'H00009'); INSERT IGNORE INTO TB_EEP_ROLE_MENU_R (ROLE_SQ, MENU_CODE) SELECT ROLE_SQ, 'H00010' FROM TB_EEP_ROLE_MENU_R WHERE MENU_CODE = 'H00006' AND NOT EXISTS (SELECT 1 FROM (SELECT MENU_CODE FROM TB_EEP_ROLE_MENU_R) R WHERE R.MENU_CODE = 'H00010');
